const groupLogsByType = (
  rawLogs: T.BuildLog[],
  filterType: FilterState,
): FilteredLog[] => {
  const logs = rawLogs.map((l, index) => ({ ...l, index }));
  if (filterType === 'all' || logs.length === 0) {
    return [{ hidden: false, logs }];
  }

  const initialState = { hidden: false, logs: [] };
  const groups = logs.reduce((acc, cur) => {
    const { error, warning } = cur;
    const logType = error ? 'errors' : warning ? 'warnings' : 'all';
    if (logType !== acc.currentType) {
      acc.groups.push({ ...initialState, logs: [cur] });
      acc.currentType = logType;
    } else {
      acc.groups[acc.groups.length - 1].logs.push(cur);
    }
    return acc;
  }, { currentType: 'all', groups: [initialState] }).groups;

  return groups.reduce((prev, cur) => {
    const isPrevHidden = prev.length > 0 ? prev[prev.length - 1].hidden : true;
    const isCurrHidden = cur.hidden;
    if (isPrevHidden === isCurrHidden) {
      prev[prev.length - 1].logs.push(...cur.logs);
    } else {
      prev.push(cur);
    }
    return prev;
  }, []);
};
