  <a-assets>
    <script id="chart-script" type="text/javascript">
      const chart = document.getElementById('chart');
      const ctx = chart.getContext('2d');

      // Generate random data
      const data = [];
      for (let i = 0; i < 10; i++) {
        data.push({
          x: i,
          y: Math.random() * 100
        });
      }

      // Set up the chart
      const chartOptions = {
        type: 'bar',
        data: data,
        options: {
          scales: {
            y: {
              beginAtZero: true
            }
          }
        }
      };

      // Render the chart
      new Chart(ctx, chartOptions);

      // Update the chart every second
      setInterval(() => {
        data.forEach((d, index) => {
          d.y = Math.random() * 100;
        });
        chartOptions.data = data;
        chart.update();
      }, 1000);
    </script>
  </a-assets>
  <a-entity chart="chart-script">
    <canvas id="chart" width="400" height="200"></canvas>
  </a-entity>
</a-scene>
```
